// Generated by AI
import React, { useState, useRef, useEffect } from 'react';

export default function Home({ onNavigate, user, onPlayAsGuest }) {
  const [modalView, setModalView] = useState(null); // null | 'level' | 'leaderboard' | 'quit'
  const [selectedLevel, setSelectedLevel] = useState(1);
  const [toast, setToast] = useState(null); // null | string
  const toastTimeoutRef = useRef(null);

  const isRegistered = user && !user.isGuest;

  // Live Galaxy Leaderboard records fetched from MySQL database
  const [leaderboard, setLeaderboard] = useState([]);
  const [loadingLeaderboard, setLoadingLeaderboard] = useState(false);
  const [leaderboardError, setLeaderboardError] = useState(null);

  const fetchLeaderboard = async () => {
    setLoadingLeaderboard(true);
    setLeaderboardError(null);
    try {
      const res = await fetch('http://localhost:5000/api/game/leaderboard');
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      if (data.success && Array.isArray(data.leaderboard)) {
        setLeaderboard(data.leaderboard);
      } else {
        setLeaderboard([]);
      }
    } catch (err) {
      console.warn('Leaderboard fetch error:', err.message);
      setLeaderboardError('Could not connect to Galaxy Mission Control database.');
    } finally {
      setLoadingLeaderboard(false);
    }
  };

  useEffect(() => {
    if (modalView === 'leaderboard') {
      fetchLeaderboard();
    }
  }, [modalView]);

  const triggerToast = (msg) => {
    if (toastTimeoutRef.current) {
      clearTimeout(toastTimeoutRef.current);
    }
    setToast(msg);
    toastTimeoutRef.current = setTimeout(() => {
      setToast(null);
    }, 4000);
  };

  useEffect(() => {
    return () => {
      if (toastTimeoutRef.current) {
        clearTimeout(toastTimeoutRef.current);
      }
    };
  }, []);

  const handlePlayClick = () => {
    if (isRegistered) {
      onNavigate('welcome');
    } else {
      // Show beautiful retro toast notification
      triggerToast('Please login to play! Or choose "Play as Guest" below.');
    }
  };

  const handleConfirmQuit = () => {
    alert('Terminal session closed. Cockpit controls in standby.');
    setModalView(null);
    onNavigate('home');
  };

  return (
    <div className="retro-auth-card home-terminal-card w-full max-w-lg mx-auto rounded-lg overflow-hidden border border-space-border shadow-glow-coral">
      {/* Beautiful Floating Retro Toast Notification */}
      {toast && (
        <div className="retro-toast-container" role="alert">
          <div className="retro-toast">
            <div className="toast-content flex items-center gap-3">
              <span className="toast-icon text-lg">🔒</span>
              <div className="toast-text-wrap flex flex-col text-left">
                <span className="toast-title font-arcade text-xs text-space-amber font-bold">LOGIN TO PLAY</span>
                <span className="toast-desc text-xs text-space-cream">{toast}</span>
              </div>
              <button
                type="button"
                className="retro-btn btn-coral toast-action-btn transition-all duration-200 hover:scale-105"
                onClick={() => onNavigate('login')}
              >
                LOGIN ▶
              </button>
              <button
                type="button"
                className="toast-close-btn text-space-muted hover:text-white transition"
                onClick={() => setToast(null)}
                aria-label="Dismiss toast"
              >
                ✕
              </button>
            </div>
            <div className="toast-progress-bar"></div>
          </div>
        </div>
      )}

      {/* Top Terminal Status Bar */}
      <div className="card-terminal-bar flex items-center gap-2 px-4 py-2 bg-space-surface border-b border-space-border">
        <span className="terminal-dot red"></span>
        <span className="terminal-dot yellow"></span>
        <span className="terminal-dot green"></span>
        <span className="terminal-title font-arcade text-xs text-space-coral">GAME_MENU // SELECT_OPTION</span>
      </div>

      {/* Main Menu View (When no modal is active) */}
      {!modalView && (
        <div className="game-menu-container flex flex-col items-center text-center p-5">
          <div className="game-menu-header mb-4">
            <div className="status-badge-retro font-arcade text-xs text-space-green tracking-wider mb-1">
              <span className="blinking-cursor">■</span> ARCADE TERMINAL READY
            </div>
            <h2 className="game-menu-title font-pixel text-xl text-space-coral tracking-wider">MAIN MISSION MENU</h2>
            <p className="game-menu-subtitle font-arcade text-xs text-space-muted mt-1">
              {isRegistered
                ? `PILOT IN COMMAND: ${user.nickname}`
                : user?.isGuest
                ? 'PILOT: GUEST • LEADERBOARD DISABLED'
                : 'SPACE FUEL MISSION CONTROL'}
            </p>
          </div>

          {/* Main Game Options */}
          <div className="game-menu-buttons flex flex-col gap-3 w-full max-w-xs">
            {/* First button: ALWAYS just says PLAY */}
            <button
              type="button"
              className="retro-btn btn-coral menu-option-btn w-full py-2.5 transition-all duration-200 hover:scale-102 active:scale-98"
              onClick={handlePlayClick}
            >
              <span className="btn-icon">▶</span> PLAY
            </button>

            {/* If not logged in: Show Play as Guest button right below Play */}
            {!isRegistered && (
              <button
                type="button"
                className="retro-btn btn-teal menu-option-btn w-full py-2.5 transition-all duration-200 hover:scale-102 active:scale-98"
                onClick={onPlayAsGuest}
              >
                <span className="btn-icon">👾</span> PLAY AS GUEST
              </button>
            )}

            <button
              type="button"
              className="retro-btn btn-outline menu-option-btn w-full py-2.5 transition-all duration-200 hover:scale-102 active:scale-98"
              onClick={() => setModalView('level')}
            >
              <span className="btn-icon">⭐</span> LEVEL
            </button>

            <button
              type="button"
              className="retro-btn btn-outline menu-option-btn w-full py-2.5 transition-all duration-200 hover:scale-102 active:scale-98"
              onClick={() => setModalView('leaderboard')}
            >
              <span className="btn-icon">🏆</span> LEADERBOARD
            </button>

            <button
              type="button"
              className="retro-btn btn-quit menu-option-btn w-full py-2.5 transition-all duration-200 hover:scale-102 active:scale-98"
              onClick={() => setModalView('quit')}
            >
              <span className="btn-icon">✕</span> QUIT
            </button>
          </div>

          <div className="game-menu-footer mt-5">
            <span className="menu-tip font-arcade text-xs text-space-dim">[ USE MOUSE OR TAP TO SELECT OPTION ]</span>
          </div>
        </div>
      )}

      {/* LEVEL MODAL */}
      {modalView === 'level' && (() => {
        const sectorData = [
          {
            num: 1,
            badge: 'SECTOR 01',
            title: 'EARTH ORBITAL ESCAPE',
            timer: '35 SECONDS',
            pts: '1,000 PTS / PUZZLE',
            hazard: 'LOW // GREEN ZONE',
            hazardColor: '#4ade80',
            objective: 'Synthesize Star Plasma fuel to break free of Earth gravity well.',
            bonus: '+2,000 PTS'
          },
          {
            num: 2,
            badge: 'SECTOR 02',
            title: 'ASTEROID BELT TRANSIT',
            timer: '25 SECONDS',
            pts: '1,500 PTS / PUZZLE',
            hazard: 'MEDIUM // ASTEROID BELT',
            hazardColor: '#f7ca74',
            objective: 'Navigate dense asteroid corridor under accelerated reactor decay.',
            bonus: '+3,000 PTS + ❤️ SHIELD REPAIR'
          },
          {
            num: 3,
            badge: 'SECTOR 03',
            title: 'HYPER-WARP GATEWAY',
            timer: '20 SECONDS',
            pts: '2,000 PTS / PUZZLE',
            hazard: 'EXTREME // GRAVITATIONAL WARP',
            hazardColor: '#ef4444',
            objective: 'Achieve terminal escape velocity & conquer deep space.',
            bonus: '+5,000 GALAXY MASTERY BONUS'
          }
        ];
        const currentSector = sectorData.find(s => s.num === selectedLevel) || sectorData[0];

        return (
          <div className="modal-inner-view">
            <div className="modal-header-row">
              <h3 className="modal-title">⭐ MISSION SECTOR SELECTOR</h3>
              <span className="modal-badge">{currentSector.badge}</span>
            </div>

            {/* Sector Tabs (Level 1, 2, 3) */}
            <div className="level-tabs-row">
              {sectorData.map(sec => (
                <button
                  key={sec.num}
                  type="button"
                  className={`level-tab-btn ${selectedLevel === sec.num ? 'active' : ''}`}
                  onClick={() => setSelectedLevel(sec.num)}
                >
                  <span>LEVEL 0{sec.num}</span>
                  <span className="level-tab-timer">⏱️ {sec.timer.split(' ')[0]}s</span>
                </button>
              ))}
            </div>

            <div className="level-status-box">
              <div className="level-header-bar">
                <span className="level-number">{currentSector.badge}</span>
                <span className="level-name">{currentSector.title}</span>
              </div>

              <div className="level-details-list">
                <div className="level-detail-item">
                  <span className="lvl-label">OBJECTIVE:</span>
                  <span className="lvl-val">{currentSector.objective}</span>
                </div>
                <div className="level-detail-item">
                  <span className="lvl-label">REACTOR TIMER:</span>
                  <span className="lvl-val" style={{ color: '#38bdf8', fontWeight: 700 }}>
                    ⏱️ {currentSector.timer}
                  </span>
                </div>
                <div className="level-detail-item">
                  <span className="lvl-label">BASE SCORE:</span>
                  <span className="lvl-val" style={{ color: '#f7ca74' }}>{currentSector.pts}</span>
                </div>
                <div className="level-detail-item">
                  <span className="lvl-label">SECTOR HAZARD:</span>
                  <span className="lvl-val" style={{ color: currentSector.hazardColor }}>
                    {currentSector.hazard}
                  </span>
                </div>
                <div className="level-detail-item">
                  <span className="lvl-label">CLEAR REWARD:</span>
                  <span className="lvl-val" style={{ color: '#4ade80' }}>{currentSector.bonus}</span>
                </div>
              </div>

              <div className="level-progress-bar-wrap">
                <span className="progress-label">MISSION READINESS &bull; LEVEL 0{selectedLevel} OF 03</span>
                <div className="progress-track">
                  <div
                    className="progress-fill"
                    style={{ width: `${(selectedLevel / 3) * 100}%` }}
                  ></div>
                </div>
              </div>
            </div>

            <div className="modal-actions-row">
              <button
                type="button"
                className="retro-btn btn-coral"
                onClick={() => {
                  if (isRegistered) {
                    onNavigate('game', { level: selectedLevel });
                  } else {
                    triggerToast('Please login to play! Or choose "Play as Guest" below.');
                  }
                }}
              >
                ▶ LAUNCH LEVEL 0{selectedLevel}
              </button>

              {!isRegistered && (
                <button
                  type="button"
                  className="retro-btn btn-teal"
                  onClick={() => {
                    onPlayAsGuest();
                    onNavigate('game', { level: selectedLevel });
                  }}
                >
                  👾 GUEST LAUNCH
                </button>
              )}

              <button
                type="button"
                className="retro-btn btn-outline"
                onClick={() => setModalView(null)}
              >
                BACK TO MENU
              </button>
            </div>
          </div>
        );
      })()}

      {/* LEADERBOARD MODAL */}
      {modalView === 'leaderboard' && (
        <div className="modal-inner-view">
          <div className="modal-header-row">
            <h3 className="modal-title">🏆 GALAXY LEADERBOARD</h3>
            <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
              <button
                type="button"
                className="leaderboard-refresh-btn"
                onClick={fetchLeaderboard}
                title="Refresh Galaxy Standings"
              >
                🔄 REFRESH
              </button>
              <span className="modal-badge">LIVE ARCHIVES</span>
            </div>
          </div>

          {/* Guest Account Leaderboard Restriction Alert */}
          {!isRegistered && (
            <div className="leaderboard-guest-banner">
              <div className="guest-banner-title">
                <span>⚠️ GUEST PILOTS EXCLUDED FROM LEADERBOARD</span>
              </div>
              <p className="guest-banner-desc">
                Guests can play without restrictions, but high scores are not recorded in galaxy rankings.
                Login or create a virtual identity to submit your scores.
              </p>
              <div className="guest-banner-buttons">
                <button
                  type="button"
                  className="retro-btn btn-teal btn-sm"
                  onClick={() => onNavigate('login')}
                >
                  LOGIN
                </button>
                <button
                  type="button"
                  className="retro-btn btn-outline btn-sm"
                  onClick={() => onNavigate('register')}
                >
                  REGISTER
                </button>
              </div>
            </div>
          )}

          <div className="leaderboard-table-wrap">
            {loadingLeaderboard ? (
              <div className="leaderboard-status-msg">
                <span>📡 QUERYING GALAXY MISSION ARCHIVES...</span>
              </div>
            ) : leaderboardError ? (
              <div className="leaderboard-empty-msg">
                <p style={{ color: '#ef4444', marginBottom: '0.5rem' }}>⚠️ {leaderboardError}</p>
                <button
                  type="button"
                  className="retro-btn btn-outline btn-sm"
                  onClick={fetchLeaderboard}
                >
                  RETRY
                </button>
              </div>
            ) : leaderboard.length === 0 ? (
              <div className="leaderboard-empty-msg">
                <p>🚀 NO FLIGHT RECORDS IN THE GALAXY ARCHIVES YET.</p>
                <p style={{ fontSize: '0.75rem', marginTop: '0.35rem', color: '#94a3b8' }}>
                  Launch a mission and synthesize star plasma to set the first galaxy high score!
                </p>
              </div>
            ) : (
              <table className="retro-table">
                <thead>
                  <tr>
                    <th>RANK</th>
                    <th>PILOT CALLSIGN</th>
                    <th>LEVEL</th>
                    <th>SCORE</th>
                  </tr>
                </thead>
                <tbody>
                  {leaderboard.map((row, index) => {
                    const rankNum = String(index + 1).padStart(2, '0');
                    const isCurrent =
                      isRegistered &&
                      user?.nickname &&
                      row.nickname?.toLowerCase() === user.nickname?.toLowerCase();
                    return (
                      <tr key={index} className={isCurrent ? 'current-pilot-row' : ''}>
                        <td className="rank-cell">#{rankNum}</td>
                        <td className="callsign-cell">
                          {row.nickname} {isCurrent && <span className="you-pill">YOU</span>}
                        </td>
                        <td className="level-cell">LVL {String(row.level || 1).padStart(2, '0')}</td>
                        <td className="score-cell">{Number(row.score).toLocaleString()}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>

          <div className="modal-actions-row">
            <button
              type="button"
              className="retro-btn btn-coral"
              onClick={() => setModalView(null)}
            >
              BACK TO MENU
            </button>
          </div>
        </div>
      )}

      {/* QUIT CONFIRMATION MODAL */}
      {modalView === 'quit' && (
        <div className="modal-inner-view quit-modal">
          <div className="modal-header-row">
            <h3 className="modal-title" style={{ color: '#f87171' }}>✕ ABORT TERMINAL SESSION?</h3>
          </div>

          <p className="quit-warning-text">
            WARNING: Leaving the terminal will end all active mission simulations and return your cockpit controls to standby mode.
          </p>

          <div className="modal-actions-row">
            <button
              type="button"
              className="retro-btn btn-quit-confirm"
              onClick={handleConfirmQuit}
            >
              YES, QUIT TERMINAL
            </button>
            <button
              type="button"
              className="retro-btn btn-outline"
              onClick={() => setModalView(null)}
            >
              CANCEL
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
